CREATE VIEW v34607 AS SELECT *, ST_ASTEXT(ST_INTERSECTION(ST_GEOMFROMTEXT('GEOMETRYCOLLECTION(GEOMETRYCOLLECTION())'), ST_GEOMFROMTEXT('GEOMETRYCOLLECTION(GEOMETRYCOLLECTION(POINT(1 1), GEOMETRYCOLLECTION(GEOMETRYCOLLECTION())))'))) AS x1, CONCAT(LEFT(RIGHT(CONCAT('what ', CONCAT('is ', 'happening')), 9), 4), LEFT(x3.v33429, CHAR_LENGTH(x3.v33428) - 6)) AS x2 FROM v33427 AS x3 NATURAL JOIN v34103 AS x6 WHERE 2 = (7 + 1000)